<!DOCTYPE html>
<html lang="ko">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>롯데월드타워 3D 모델</title>
    <style>
        body {
            font-family: Arial, sans-serif;
            margin: 0;
            background-color: #f0f0f0;
        }
        #container {
            width: 100%;
            height: 100vh;
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
        }
        #model-name {
            position: absolute;
            top: 10px;
            left: 10px;
            font-size: 18px;
            color: #333;
        }
        #controls {
            position: absolute;
            bottom: 10px;
            left: 10px;
            font-size: 18px;
            color: #333;
        }
        #description {
            position: absolute;
            top: 50px;
            left: 10px;
            font-size: 18px;
            color: #333;
        }
    </style>
</head>
<body>
    <div id="model-name">llama-3.3-70b-bedrock</div>
    <div id="description">
        롯데월드타워는 서울에 위치한 높이 555m, 지상 123층으로 위로 갈수록 기준층 면적과 건물 외곽이 좁아지는 형태입니다. KPF는 형태와 외관에 한국 도자기의 선을 참고했다고 설명합니다.
    </div>
    <div id="container">
        <canvas id="canvas" width="800" height="600"></canvas>
        <div id="controls">
            <button id="reset-button">초기화</button>
            <button id="zoom-in-button">확대</button>
            <button id="zoom-out-button">축소</button>
        </div>
    </div>

    <script src="../runtime/three-runtime.js"></script>
    <script>
        // Three.js 설정
        const scene = new THREE.Scene();
        const camera = new THREE.PerspectiveCamera(75, 800 / 600, 0.1, 1000);
        const renderer = new THREE.WebGLRenderer({
            canvas: document.getElementById('canvas'),
            antialias: true
        });
        renderer.setSize(800, 600);

        // OrbitControls 설정
        const controls = new THREE.OrbitControls(camera, renderer.domElement);

        // 모델 생성
        const geometry = new THREE.BoxGeometry(1, 1, 1);
        const material = new THREE.MeshBasicMaterial({ color: 0x00ff00 });
        const cube = new THREE.Mesh(geometry, material);
        scene.add(cube);

        // 롯데월드타워 모델 생성
        const lotteTowerGeometry = new THREE.BoxGeometry(10, 555, 10);
        const lotteTowerMaterial = new THREE.MeshBasicMaterial({ color: 0x0000ff });
        const lotteTower = new THREE.Mesh(lotteTowerGeometry, lotteTowerMaterial);
        scene.add(lotteTower);

        // 배치도, 기준층 평면도, 입면도, 단면도 생성
        const floorPlanGeometry = new THREE.PlaneGeometry(10, 10);
        const floorPlanMaterial = new THREE.MeshBasicMaterial({ color: 0xffffff });
        const floorPlan = new THREE.Mesh(floorPlanGeometry, floorPlanMaterial);
        scene.add(floorPlan);

        const elevationGeometry = new THREE.PlaneGeometry(10, 555);
        const elevationMaterial = new THREE.MeshBasicMaterial({ color: 0xffffff });
        const elevation = new THREE.Mesh(elevationGeometry, elevationMaterial);
        scene.add(elevation);

        const sectionGeometry = new THREE.PlaneGeometry(10, 10);
        const sectionMaterial = new THREE.MeshBasicMaterial({ color: 0xffffff });
        const section = new THREE.Mesh(sectionGeometry, sectionMaterial);
        scene.add(section);

        // 애니메이션
        function animate() {
            requestAnimationFrame(animate);
            controls.update();
            renderer.render(scene, camera);
        }
        animate();

        // 버튼 이벤트
        document.getElementById('reset-button').addEventListener('click', () => {
            controls.reset();
        });
        document.getElementById('zoom-in-button').addEventListener('click', () => {
            controls.dollyIn();
        });
        document.getElementById('zoom-out-button').addEventListener('click', () => {
            controls.dollyOut();
        });
    </script>
</body>
</html>
